"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[5226],{45226:e=>{e.exports=JSON.parse('{"meta":{"title":"G\xf6n\xfcll\xfc Ol - iMuslim Life","description":"D\xfcnyan\u0131n d\xf6rt bir yan\u0131ndaki M\xfcsl\xfcmanlar\u0131n namaz\u0131 vaktinde k\u0131lmas\u0131na ve Kur\u2019an\u2019\u0131 kendi dillerinde okumas\u0131na yard\u0131m edin. \xc7evirmen, k\xe2ri, g\xf6zden ge\xe7iren, yazar, test eden veya cami el\xe7isi olarak g\xf6n\xfcll\xfc olun."},"chip":"G\xf6n\xfcll\xfc olun","h1":"Yetenekleriniz bir sadaka-i c\xe2riye olabilir","lede":"Salat-e-Mustaqeem ve iMuslim Life \xfccretsizdir, reklams\u0131zd\u0131r ve d\xfcnyan\u0131n her yerinden M\xfcsl\xfcmanlar taraf\u0131ndan her g\xfcn kullan\u0131l\u0131r. Birka\xe7 saatiniz, birinin namaz\u0131n\u0131 vaktinde k\u0131lmas\u0131na, Kur\u2019an\u2019\u0131 kendi dilinde anlamas\u0131na veya en yak\u0131n camiyi bulmas\u0131na tekrar tekrar vesile olabilir.","heroCta":"G\xf6n\xfcll\xfc olmak i\xe7in e-posta g\xf6nderin","hadith":{"text":"\u201cKim bir hayra vesile olursa, ona o hayr\u0131 yapan\u0131n sevab\u0131 kadar sevap vard\u0131r.\u201d","source":"Hz. Muhammed (s.a.v.), Sahih-i M\xfcslim 1893"},"why":"\xc7evirdi\u011finiz her kelimeyi hi\xe7 tan\u0131\u015fmayaca\u011f\u0131n\u0131z insanlar okur. Kaydetti\u011finiz her tilavet evlerde, arabalarda ve camilerde dinlenir. Biz k\xfc\xe7\xfck bir ekibiz; bu \xe7al\u0131\u015fmay\u0131 her dile ve d\xfcnyan\u0131n her k\xf6\u015fesine ula\u015ft\u0131ran g\xf6n\xfcll\xfclerdir.","rolesH2":"Nas\u0131l yard\u0131m edebilirsiniz","rolesSub":"Size uygun olan\u0131 se\xe7in. Teknik deneyim gerekmez; samimiyet, \xf6zen ve biraz zaman yeterli.","roleCta":"Yard\u0131m edebilirim","roles":{"translate":{"title":"\xc7evirmenler","text":"Uygulamay\u0131, web sitesini, dualar\u0131 ve haftal\u0131k hik\xe2yeleri kendi dilinize ta\u015f\u0131y\u0131n: T\xfcrk\xe7e, Arap\xe7a, Urduca, Frans\u0131zca, \u0130spanyolca, Endonezce, Malayca, Bengalce, Hint\xe7e ve daha fazlas\u0131. Her \xe7eviri yay\u0131ndan \xf6nce kontrol edilir.","time":"Haftada 1\u20132 saatten ba\u015flayarak"},"recite":{"title":"K\xe2riler","text":"Allah size g\xfczel bir ses ve do\u011fru tecvid nasip ettiyse, d\xfcnyan\u0131n d\xf6rt bir yan\u0131ndaki dinleyiciler i\xe7in Kur\u2019an tilaveti, dua veya ezan kaydedin. Kay\u0131t ve d\xfczenlemede yard\u0131mc\u0131 oluyoruz.","time":"Kendi temponuzda kaydedin"},"review":{"title":"\xc2limler ve g\xf6zden ge\xe7irenler","text":"\u0130lim talebeleri, imamlar ve \xf6\u011fretmenler: \xe7evirilerin, hik\xe2yelerin ve yar\u0131\u015fma cevaplar\u0131n\u0131n do\u011frulu\u011funu ve kaynaklar\u0131n\u0131 kontrol edin; yay\u0131mlad\u0131\u011f\u0131m\u0131z her \u015fey g\xfcvenilir olsun.","time":"F\u0131rsat bulduk\xe7a inceleyin"},"write":{"title":"Yazarlar ve hik\xe2ye anlat\u0131c\u0131lar\u0131","text":"Aileler ve \xe7ocuklar i\xe7in Peygamberlerin, Sahabelerin ve Siyer\u2019in haftal\u0131k hik\xe2yelerini yazmaya yard\u0131m edin; T\xfcrk\xe7e veya ba\u015fka bir dilde, her zaman sahih kaynaklardan.","time":"Ayda bir hik\xe2ye bile b\xfcy\xfck bir katk\u0131"},"test":{"title":"Test edenler","text":"Yeni \xf6zellikleri yay\u0131ndan \xf6nce iPhone, Android veya Alexa\u2019da deneyin ve neyin yanl\u0131\u015f ya da kafa kar\u0131\u015ft\u0131r\u0131c\u0131 geldi\u011fini bize s\xf6yleyin. Taze bir g\xf6z, bizim ka\xe7\u0131rd\u0131\u011f\u0131m\u0131z\u0131 g\xf6r\xfcr.","time":"Her s\xfcr\xfcmde birka\xe7 dakika"},"masjid":{"title":"Cami el\xe7ileri","text":"Yerel caminizin kamet ve cuma vakitlerini yay\u0131mlamas\u0131na yard\u0131m edin; cemaati bunlar\u0131 uygulamada, web sitesinde ve Alexa\u2019da g\xf6rs\xfcn. Her cami i\xe7in \xfccretsiz.","time":"Tek bir sohbet b\xfct\xfcn bir cemaate hizmet edebilir"}},"stepsH2":"Nas\u0131l i\u015fler","steps":{"s1":{"title":"Bize yaz\u0131n","text":"Hangi rol\xfc istedi\u011finizi, hangi dilleri bildi\u011finizi ve kendinizi biraz anlat\u0131n."},"s2":{"title":"Size bizzat d\xf6n\xfcyoruz","text":"K\u0131sa bir rehber ve ilk k\xfc\xe7\xfck g\xf6revle size geri d\xf6n\xfcyoruz."},"s3":{"title":"Eme\u011finiz yay\u0131na girer","text":"\u0130ncelemeden sonra katk\u0131n\u0131z d\xfcnyan\u0131n d\xf6rt bir yan\u0131ndaki insanlara ula\u015f\u0131r."}},"promiseH2":"Bizden neler bekleyebilirsiniz","promise":{"p1":{"title":"Sizin zaman\u0131n\u0131z, sizin temponuz","text":"Asgari taahh\xfct yok. Elinizden geldi\u011finde yard\u0131m edin, gerekti\u011finde ara verin."},"p2":{"title":"\u0130sterseniz ad\u0131n\u0131zla","text":"Size ad\u0131n\u0131zla te\u015fekk\xfcr etmekten mutluluk duyar\u0131z ya da yard\u0131m\u0131n\u0131z\u0131 sizinle Allah aras\u0131nda tutar\u0131z. Se\xe7im sizin."},"p3":{"title":"Do\u011frulu\u011fa \xf6zen","text":"Dini i\xe7erik yay\u0131mlanmadan \xf6nce incelenir ve kaynakland\u0131r\u0131l\u0131r. Bu y\xfck\xfc asla tek ba\u015f\u0131n\u0131za ta\u015f\u0131mazs\u0131n\u0131z."},"p4":{"title":"Gizlili\u011finize sayg\u0131","text":"E-postan\u0131z\u0131 yaln\u0131zca sizinle \xe7al\u0131\u015fmak i\xe7in kullan\u0131r, asla payla\u015fmaz veya bir e-posta listesine eklemeyiz."}},"finalH2":"Yard\u0131ma haz\u0131r m\u0131s\u0131n\u0131z?","finalText":"Bize tek bir e-posta g\xf6nderin. Nereye uydu\u011funuzdan emin olmasan\u0131z bile yaz\u0131n; do\u011fru yeri birlikte bulaca\u011f\u0131z, in\u015fallah."}')}}]);